def process(mmc1) -> pd.DataFrame:
    import pandas as pd

    df = mmc1.copy()

    # Identify histology column and filter to serous
    hist_col = None
    for c in df.columns:
        if str(c).strip().lower() == 'histologic_type':
            hist_col = c
            break
    if hist_col is None:
        return pd.DataFrame([{'error':'Histologic_type column not found', 'columns': ','.join(df.columns)}])

    serous = df[df[hist_col].astype(str).str.strip().str.lower().str.contains('serous', na=False)].copy()

    # Find a likely "variants per Mbp" column (case-insensitive, ignore underscores/spaces)
    def norm(s: str) -> str:
        return ''.join(ch for ch in str(s).lower() if ch.isalnum())

    target_col = None
    for c in serous.columns:
        nc = norm(c)
        if 'variant' in nc and ('mbp' in nc or 'megabase' in nc or 'permb' in nc or 'permbp' in nc):
            target_col = c
            break
        if nc in {'variantspermbp','variantspermb','variantsmbp','variantpermbp'}:
            target_col = c
            break
    if target_col is None:
        # fallback: typical naming in genomics tables
        for c in serous.columns:
            nc = norm(c)
            if nc in {'tmb','tumormutationalburden','mutationburden'}:
                target_col = c
                break

    if target_col is None:
        # Return diagnostics: candidate columns containing 'variant' or 'mbp'
        candidates = [c for c in df.columns if ('variant' in str(c).lower() or 'mbp' in str(c).lower() or 'tmb' in str(c).lower())]
        return pd.DataFrame([{
            'error': 'No variants-per-Mbp/TMB column found',
            'nSerous': int(serous.shape[0]),
            'candidateColumns': '; '.join(map(str, candidates))
        }])

    # Coerce to numeric
    vals = pd.to_numeric(serous[target_col].astype(str).str.replace(',', '', regex=False), errors='coerce')
    med = float(vals.median())

    return pd.DataFrame([{
        'histologyFilter': 'contains(serous) on Histologic_type',
        'nTotal': int(df.shape[0]),
        'nSerous': int(serous.shape[0]),
        'variantsPerMbpColumn': str(target_col),
        'medianVariantsPerMbp': med
    }])
